import React from 'react';

import { showModal } from '@ui-kit/Modal';

import ScheduleModal from './index';

export const showScheduleModal = (id_hiking: number, date: Date, title = 'Расписание на день') => {
  showModal({
    title,
    children: <ScheduleModal id_hiking={id_hiking} date={date} />,
  });
};
