import React, { useContext } from 'react';

import CalendarWeek from '@pohodnik/icons/svg/DateTime/CalendarWeek';
import InfoCircle from '@pohodnik/icons/svg/Signs/InfoCircle';

import { getHikingDataAsync } from '@apps/Hiking/@services/hiking.service';
import {
  addHikingDuty,
  deleteHikingDuty,
  editHikingDuty,
  getHikingDuty,
} from '@apps/Hiking/@services/hikingDuty.service';
import { IHikingDuty } from '@apps/Hiking/@types/hiking.baseTypes';
import { IHikingData } from '@apps/Hiking/@types/hiking.types';
import DayInfoWidget from '@apps/Hiking/one/components/DayInfoWidget';
import { showScheduleModal } from '@apps/Hiking/schedule/components/ScheduleModal/scheduleModalHelper';
import PageLoader from '@components/PageLoader';
import { getSQLDate } from '@helpers/dateHelper';
import { err } from '@helpers/notificationHelper';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import { confirmModal } from '@ui-kit/Modal';

import style from './style.module.less';
import { AuthContext } from '../../../../contexts/AuthContext';

interface IHikingDutyTableProps {
  id_hiking: number;
}

const HikingDutyTable: React.FC<IHikingDutyTableProps> = ({ id_hiking }) => {
  const [isLoading, setIsLoading] = React.useState(true);

  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [duty, setDuty] = React.useState<IHikingDuty[]>([]);

  const authContext = useContext(AuthContext);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const hd = await getHikingDataAsync(id_hiking);
        setHikingData(hd);

        const hda = await getHikingDuty(id_hiking);
        setDuty(hda);
      } finally {
        setIsLoading(false);
      }
    };

    init().catch(err);
  }, [id_hiking]);
  const hikers = React.useMemo(() => (hikingData ? hikingData.hikers.reverse() : []), [hikingData]); // инициалы

  if (isLoading || hikingData == null) {
    return <PageLoader />;
  }

  let d = hikingData.start.getTime();
  const days: Date[] = [];

  while (d < hikingData.finish.getTime()) {
    days.push(new Date(d));
    d += 86400000;
  }

  const summaries: number[] = [];

  const handleChangeDutyState = async (date: Date, id_user: number, forceDutyState?: boolean) => {
    const current = duty.find(
      (du) => du.date.toLocaleDateString() === date.toLocaleDateString() && id_user === du.id_user,
    );

    if (current) {
      await deleteHikingDuty(id_hiking, current.id);
      setDuty((cur) => cur.filter((x) => x.id !== current.id));
    } else {
      if (forceDutyState === false) {
        return;
      }

      const id = await addHikingDuty({
        id_hiking: id_hiking.toString(),
        comment: '',
        id_user: id_user.toString(),
        date: getSQLDate(date).substring(0, 10),
      });
      if (!authContext?.user) {
        return;
      }

      setDuty((cur) => {
        if (!authContext.user) return cur;
        return cur.concat({
          id,
          id_user: id_user,
          date,
          comment: '',
          created: {
            id: +authContext.user.id,
            name: authContext.user.name,
            date: new Date(),
          },
          user: {
            id: id_user,
            name: id_user.toString(),
            photo: '',
          },
          updated: null,
        });
      });
    }
  };

  const handleEdit = async (dutyObj: IHikingDuty) => {
    const comment = prompt('Коммент', dutyObj.comment) ?? '';
    await editHikingDuty({ comment, id: dutyObj.id.toString(), id_hiking: id_hiking.toString() });
    setDuty((cur) => cur.map((c) => (c.id === dutyObj.id ? { ...c, comment } : c)));
  };

  const handleAutoFill = async () => {
    const ok = await confirmModal({
      title: 'Автозаполнение',
      children: (
        <div>
          Заполнить с использованием алгоритма&nbsp;
          <a href={'https://github.com/IlyaCherkasov'} target="_blank" rel="noreferrer">
            Ильи Черкасова
          </a>
          ?
        </div>
      ),
      confirmText: 'Заполнить',
    });
    if (!ok) {
      return;
    }

    const membersInDay = 2;
    const membersCount = hikingData.hikers.length;
    let memberIndex = -1;

    const dutyMap: Record<string, number[]> = {};

    days.forEach((oneDay) => {
      const k = oneDay.toLocaleDateString();
      dutyMap[k] = [];
      Array(membersInDay)
        .fill(null)
        .forEach(() => {
          if (memberIndex < hikingData.hikers.length - 1) {
            memberIndex++;
          } else {
            memberIndex = 0;
          }

          dutyMap[k].push(memberIndex);
        });
    });

    const membersGaps = new Array(membersCount).fill(1);
    let nextMemberIndex = 0;
    const freeMembers = new Array(membersCount).fill(true);

    const matrix: Array<boolean[]> = [];

    days.forEach((oneDay) => {
      const matrixRow = new Array(membersCount).fill(false);
      const currentMemberIndex = nextMemberIndex;
      matrixRow[currentMemberIndex % membersCount] = true;
      matrixRow[
        (currentMemberIndex + membersGaps[currentMemberIndex % membersCount]) % membersCount
      ] = true;
      freeMembers[currentMemberIndex % membersCount] = true;
      freeMembers[
        (currentMemberIndex + membersGaps[currentMemberIndex % membersCount]) % membersCount
      ] = true;
      nextMemberIndex =
        membersGaps[currentMemberIndex % membersCount] <= 1
          ? currentMemberIndex + 2
          : currentMemberIndex + 1;
      membersGaps[currentMemberIndex % membersCount] += 1;
      matrix.push(matrixRow);

      matrixRow.forEach((isDuty, i) => handleChangeDutyState(oneDay, hikers[i].idUser, isDuty));
    });
  };

  return (
    <table className={style.table}>
      <thead>
        <tr>
          <th>
            <div className="d-flex justify-content-between align-items-center">
              День
              <small>
                <PohButton
                  className="d-print-none"
                  size={ButtonSize.Small}
                  icon={true}
                  onClick={handleAutoFill}
                >
                  <CalendarWeek />
                </PohButton>
              </small>
            </div>
          </th>
          {hikers.map((h) => (
            <th
              style={{ width: `${100 / (hikers.length + 1)}%` }}
              className="text-center"
              key={`th${h.idUser}`}
            >
              {h.surname.substr(0, 1)}
              {h.name.substr(0, 1)}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {days.map((oneDay, di) => {
          const k = oneDay.toLocaleDateString();
          return (
            <tr key={k}>
              <td>
                <div className="d-flex align-items-center">
                  <div className="w-25 text-end me-2 pe-2 border-end">
                    <b>{di + 1}</b>
                  </div>
                  <DayInfoWidget
                    date={oneDay}
                    onClick={() => showScheduleModal(id_hiking, oneDay)}
                    title="Клик чтобы посмотреть расписание на день"
                  />
                </div>
              </td>
              {hikers.map((h, i) => {
                const dutyObj = duty.find(
                  (du) =>
                    du.date.toLocaleDateString() === oneDay.toLocaleDateString() &&
                    h.idUser === du.id_user,
                );
                const isDuty = !!dutyObj;
                if (!summaries[i]) {
                  summaries[i] = 0;
                }
                if (isDuty) {
                  summaries[i]++;
                }
                return (
                  <td style={{ padding: 0 }} height={32} key={`${k}-${h.idUser}`}>
                    <PohButton
                      block
                      size={ButtonSize.Small}
                      variant={isDuty ? ButtonVariant.Success : ButtonVariant.Light}
                      onClick={(e) =>
                        e.ctrlKey && dutyObj
                          ? handleEdit(dutyObj)
                          : handleChangeDutyState(oneDay, h.idUser)
                      }
                      title={[
                        dutyObj && [dutyObj.comment].join('\t'),
                        dutyObj &&
                          [
                            'Создано',
                            dutyObj.created.name,
                            dutyObj.created.date.toLocaleString(),
                          ].join('\t'),
                        dutyObj?.updated &&
                          [
                            'Обновлено',
                            dutyObj.updated.name,
                            dutyObj.updated.date.toLocaleString(),
                          ].join('\t'),
                      ]
                        .filter(Boolean)
                        .join('\n')}
                      style={{ height: '100%' }}
                    >
                      {dutyObj?.comment?.length && dutyObj.comment.length > 0 ? (
                        <small
                          title={[dutyObj.comment, 'CTRL+Click для редактирования'].join(
                            '\n--------------------------------\n',
                          )}
                        >
                          <InfoCircle className={'d-print-none'} />
                          <em className="d-none d-print-block">{dutyObj.comment}</em>
                        </small>
                      ) : (
                        '\u00a0'
                      )}
                    </PohButton>
                  </td>
                );
              })}
            </tr>
          );
        })}
      </tbody>
      <tfoot>
        <tr className="text-muted">
          <th className="text-end">Итого раз:</th>
          {hikers.map((h, i) => {
            return (
              <th className="text-center" key={`${h.idUser}-summary`}>
                {summaries[i]}
              </th>
            );
          })}
        </tr>
      </tfoot>
    </table>
  );
};

export default HikingDutyTable;
