import React from 'react';

import clsx from 'clsx';

import { getHikingScheduleForDate } from '@apps/Hiking/@services/hikingSchedule.service';
import { IHikingScheduleItem } from '@apps/Hiking/@types/hiking.baseTypes';
import PohAlert from '@ui-kit/Alert';
import PohLoader from '@ui-kit/Loader';

import styles from './style.module.less';
import ScheduleItem from '../ScheduleItem';

interface IScheduleModalProps {
  id_hiking: number;
  date: Date;
}

const ScheduleModal: React.FC<IScheduleModalProps> = ({ id_hiking, date }) => {
  const [data, setData] = React.useState<IHikingScheduleItem[]>([]);
  const [isLoading, setIsLoading] = React.useState(false);
  const [error, setError] = React.useState('');

  React.useEffect(() => {
    async function fetch() {
      try {
        setIsLoading(true);
        const res = await getHikingScheduleForDate(id_hiking, date);
        setData(res);
      } catch (e) {
        setError((e as Error).message);
      } finally {
        setIsLoading(false);
      }
    }
    fetch();
  }, [id_hiking, date]);

  if (isLoading) {
    return <PohLoader />;
  }

  if (error.length) {
    return <PohAlert>{error}</PohAlert>;
  }

  return (
    <div className={styles.scheduleList}>
      {data.map((scheduleItem, index, items) => (
        <ScheduleItem
          key={scheduleItem.id}
          id_hiking={+id_hiking}
          scheduleItem={scheduleItem}
          className={clsx(
            index % 2 === 0 && 'bg-light',
            index === items.length - 1 && 'border-bottom',
          )}
        />
      ))}
    </div>
  );
};

export default ScheduleModal;
